    lighting.addColorStop(0,'#ffffff30');lighting.addColorStop(.58,'#ffffff00');lighting.addColorStop(1,style==='comic'?'#001c4230':'#02293255');
    ctx.fillStyle=lighting;ctx.beginPath();ctx.arc(g.cx,g.cy,g.radius,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle=style==='comic'?'#76e9ff':'#ffffff55';ctx.lineWidth=style==='comic'?3:1.3;ctx.stroke();
